import{d as g,C as a,o as p,c as h,E as i,a3 as t}from"./chunks/framework.D4-ViStF.js";const x=JSON.parse('{"title":"蹇卦","description":"第三十九卦·水山蹇——险在前而能止。蹇是处境，不是动作；见险而能止，是看清这份处境之后提炼出的应对智慧。","frontmatter":{"title":"蹇卦","description":"第三十九卦·水山蹇——险在前而能止。蹇是处境，不是动作；见险而能止，是看清这份处境之后提炼出的应对智慧。","category":"hexagram","aliases":["蹇","水山蹇"],"source":["《周易》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/hexagrams/39-shuishanjian.md","filePath":"yijing/hexagrams/39-shuishanjian.md","lastUpdated":1789714390000}'),d={name:"yijing/hexagrams/39-shuishanjian.md"},b=g({...d,setup(u){const o=[{id:"wang",term:"往",pinyin:"wǎng",meaning:"向外、前进。",context:"泰卦「小往大来」、否卦「大往小来」皆以「往」为外出。四个「往蹇」的用例里，往 + 险难名词语法通顺，往 + 止则自相矛盾——这是「蹇」不含「止」义的内部铁证。"},{id:"lai",term:"来",pinyin:"lái",meaning:"向内、退返，与「往」对举。",context:"初六「来誉」、九三「来反」、六四「来连」、上六「来硕」，皆以「来」为退返本位。"},{id:"fan",term:"反",pinyin:"fǎn",meaning:"折返，是空间动作，不是「反躬自省」。",context:"复卦「反复其道」、泰卦九三「无往不复」。"},{id:"lian",term:"连",pinyin:"lián",meaning:"联结、依靠。",context:"六四被九三、九五两阳爻环抱。此处取「联结」义，依据小象「当位实也」的肯定语气；「牵连拖累」的读法仍留有模糊地带。"},{id:"peng",term:"朋",pinyin:"péng",meaning:"同类聚合，不是「友谊」。",context:"呼应坤卦「西南得朋」「乃与类行」。"},{id:"shuo",term:"硕",pinyin:"shuò",meaning:"历经消耗仍完整保留的成果。",context:"剥卦上九「硕果不食」。"},{id:"jianjian",term:"蹇蹇",pinyin:"jiǎn jiǎn",meaning:"险难反复叠加。叠字表程度加深，不是「止而反身」。"},{id:"feigong",term:"匪躬",pinyin:"fěi gōng",meaning:"不是因自身私利所致。匪即非，躬即自身。",context:"六二小象「终无尤也」，以「匪躬之故」为支撑判定的理由。"},{id:"daren",term:"大人",pinyin:"dà rén",meaning:"德位兼备、能带人出险的人。",context:"卦辞「利见大人」的承诺，在上六兑现——所见正是九五。"}],e=[{position:"初六",type:"yin",text:"往蹇来誉。",xiang:"往蹇来誉，宜待也。",textModern:"前往则遇险，退返则得称许。尚未深入险境、退路仍在时，止步本身就是值得称许的事。",xiangModern:"往蹇来誉，是说此时宜于等待。"},{position:"六二",type:"yin",text:"王臣蹇蹇，匪躬之故。",xiang:"王臣蹇蹇，终无尤也。",textModern:"身为王臣，险难反复叠加；这份艰难不是因自身私利招致。守得住这份清白，终究无过咎。",xiangModern:"王臣蹇蹇而终无过咎——因为这份苦不为己。"},{position:"九三",type:"yang",text:"往蹇来反。",xiang:"往蹇来反，内喜之也。",textModern:"前往则入险，折返则回本位。艮之主处在山域最后的边界，这一次折返是结构性的回归，内心安然。",xiangModern:"往蹇来反，因为回到本位而内心喜悦。"},{position:"六四",type:"yin",text:"往蹇来连。",xiang:"往蹇来连，当位实也。",textModern:"前往则遇险，退返则联结。刚入坎险、自知柔弱，转而依靠左右两阳爻——老实待在能左右逢源的位置上，本身就是踏实。",xiangModern:"往蹇来连，因为当位而踏实。"},{position:"九五",type:"yang",text:"大蹇朋来。",xiang:"大蹇朋来，以中节也。",textModern:"险难的核心与君位的责任重合，是为大蹇；而同类自然聚拢而来。不靠乞求，靠中正有节的定力。",xiangModern:"大蹇朋来，因为中正有节。"},{position:"上六",type:"yin",text:"往蹇来硕，吉，利见大人。",xiang:"往蹇来硕，志在内也。利见大人，以从贵也。",textModern:"历尽全险而带回完整的成果，吉；宜见大人。脱险而不弃同伴，心仍系着尚在险中的九五。",xiangModern:"往蹇来硕，志在于内——心系险中的同伴；利见大人，是追随尊贵者。"}];return(m,n)=>{const r=a("DaoHexagramViewer"),s=a("DaoHexagramYaoCards"),l=a("DaoKeywordCards");return p(),h("div",null,[i(r,{name:"蹇",fullName:"水山蹇",upper:"☵",lower:"☶",guaCi:"蹇，利西南，不利东北。利见大人，贞吉。",pinyin:["jiǎn"],element:"金",direction:"西",insight:"山上有水，行路维艰。止不是认输，是看清险在前而不硬闯——先反身修德，再等同类相聚。",guaSlug:"39shuishanjian",lines:e}),n[0]||(n[0]=t('<h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>蹇，难也，险在前也。见险而能止，知矣哉。蹇利西南，往得中也。不利东北，其道穷也。利见大人，往有功也。当位贞吉，以正邦也。蹇之时用大矣哉。</p><p>逐句释义：</p><ul><li><strong>蹇，难也，险在前也</strong> —— 蹇就是难；难在何处？险在眼前。这一句定的是<strong>处境</strong>，不是动作。</li><li><strong>见险而能止，知矣哉</strong> —— 看见险能停下来，这是智。注意：这是圣人观察「坎上艮下」这个结构之后提炼出的<strong>应对智慧</strong>，不等于「蹇」这个字本身携带「止」的字义——用法层的事实以爻辞为准，见下「字词释义」与「三问解读」。</li><li><strong>蹇利西南，往得中也</strong> —— 西南为坤，平易、包容、同类所居；往那边走才得中道。</li><li><strong>不利东北，其道穷也</strong> —— 东北为艮，山止之处，路已穷尽。与坤卦「西南得朋，东北丧朋」同一套方位语法：<strong>利于靠近同类，不利于孤身深入</strong>。</li><li><strong>利见大人，往有功也</strong> —— 见大人，前往才有功。</li><li><strong>当位贞吉，以正邦也</strong> —— 各爻当位而守正，故吉；以之可以正邦。</li><li><strong>蹇之时用大矣哉</strong> —— 蹇这个时机的功用，很大。</li></ul><blockquote><p><strong>处境哲学</strong>：蹇是一个描述「你正处在什么位置」的字，不是描述「你该做什么动作」的字。真正的功课，是从处境里长出智慧——见险而能止。</p></blockquote><h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>山上有水，蹇。君子以反身修德。</p><p>山上有水、水在山上，流不得畅，行路维艰，这是蹇之象。君子由此悟到：<strong>反身修德</strong>。</p><p>遇蹇向外求，越求越蹇；回头修自己，反而有了出路。蹇卦给出的第一个动作不是「突围」，是<strong>反身</strong>——先看清楚自己站在哪里、身上缺什么，再谈走出去。</p><blockquote><p><strong>反身哲学</strong>：险在眼前时，最容易的动作是往前冲，最难的动作是回头看自己。蹇卦把后者放在第一位。</p></blockquote><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',11)),i(s,{element:"金",guaSlug:"39shuishanjian",glossary:o,items:e}),n[1]||(n[1]=t('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><p>旅程开始，人还站在山上（艮）；过了九三，才真正踏进水里（坎）。卦辞先立规矩——「利西南，不利东北，利见大人，贞吉」：靠近同类（西南）而非孤军深入（东北），守住正道，终能遇见能带你出去的人。这四句不是抽象的教诫，是接下来六爻要一步步兑现的承诺。</p><h3 id="初六-·-往蹇-来誉" tabindex="-1">初六 · 往蹇，来誉 <a class="header-anchor" href="#初六-·-往蹇-来誉" aria-label="Permalink to &quot;初六 · 往蹇，来誉&quot;">​</a></h3><ul><li>卦之初，尚未深入险境，退路仍在</li><li><strong>往</strong>：遇蹇；<strong>来</strong>：得誉</li></ul><p>这是最轻的一步。止步的成本最低时，止步本身就值得称许——<strong>主动选择的止</strong>。</p><blockquote><p>止的三种形态之一：此刻止步，成本最低，也最容易。</p></blockquote><h3 id="六二-·-王臣蹇蹇-匪躬之故" tabindex="-1">六二 · 王臣蹇蹇，匪躬之故 <a class="header-anchor" href="#六二-·-王臣蹇蹇-匪躬之故" aria-label="Permalink to &quot;六二 · 王臣蹇蹇，匪躬之故&quot;">​</a></h3><ul><li>艮之中，尚未入坎，责任已经压下来（「王臣」）</li><li><strong>蹇蹇</strong>：险难反复叠加，不是「止而反身」</li><li><strong>匪躬</strong>：这份艰难不是因自身私利招致</li></ul><p>六二不再有初六那种自由。责任所在，没有退路，也无法前进，只能站在原地硬扛。他靠的不是行动，是这份清白——小象「终无尤也」，正是以「匪躬之故」为支撑判定的理由。</p><blockquote><p>止的三种形态之二：这不是美德，是<strong>不可能拥有的止</strong>——想退，退不了。</p></blockquote><h3 id="九三-·-往蹇-来反" tabindex="-1">九三 · 往蹇，来反 <a class="header-anchor" href="#九三-·-往蹇-来反" aria-label="Permalink to &quot;九三 · 往蹇，来反&quot;">​</a></h3><ul><li>艮之最高爻，艮之主，紧邻坎，是山域最后的边界</li><li>天生带着「止」的性向：往，前面就是险；来，回到的正是自己的本位</li></ul><p>这一次折返不是逃避，是山域留给人的最后一次回头机会，也是山域给他的最后一次确认。象传说「内喜之也」——回到自己站得住的地方，那是一种踏实的安心。</p><blockquote><p>止的三种形态之三：<strong>结构性、回家般的止</strong>。</p></blockquote><h3 id="六四-·-往蹇-来连" tabindex="-1">六四 · 往蹇，来连 <a class="header-anchor" href="#六四-·-往蹇-来连" aria-label="Permalink to &quot;六四 · 往蹇，来连&quot;">​</a></h3><ul><li>坎之初爻，刚踏入险，阴柔而自知柔弱，独木难支</li><li>同时被九三、九五两个阳爻左右环抱</li><li><strong>连</strong>：联结、依靠（依小象「当位实也」的肯定语气取此读法）</li></ul><p>这是全卦第一个「独自扛不住、必须靠关系才能站住」的位置——<strong>从独自应对到主动联结的转折点</strong>。不是硬撑，是主动联结、依靠身边的力量。小象说「当位实也」：老实地待在能左右逢源的位置上，这本身就是一种踏实。</p><blockquote><p>转折：下三爻问的是「止还是往」，从这里开始，问题变成「靠什么活下来」。</p></blockquote><h3 id="九五-·-大蹇-朋来" tabindex="-1">九五 · 大蹇，朋来 <a class="header-anchor" href="#九五-·-大蹇-朋来" aria-label="Permalink to &quot;九五 · 大蹇，朋来&quot;">​</a></h3><ul><li>坎之中爻，险难最深处，同时又是君位——险的核心与责任的核心结构性重合，故曰<strong>大蹇</strong></li><li>中且正，被六四、上六两个阴爻环抱</li><li><strong>朋来</strong>：同类因「中节」自然聚拢而来</li></ul><p>不是他去乞求，是他的品质本然地召唤了同类相聚（呼应坤卦「西南得朋」「乃与类行」）。这是全卦第一次，<strong>险与援同时并存</strong>。</p><blockquote><p>定力即是磁场：中正而有节，不必呼求，同类自会靠拢。</p></blockquote><h3 id="上六-·-往蹇-来硕-吉-利见大人" tabindex="-1">上六 · 往蹇，来硕，吉，利见大人 <a class="header-anchor" href="#上六-·-往蹇-来硕-吉-利见大人" aria-label="Permalink to &quot;上六 · 往蹇，来硕，吉，利见大人&quot;">​</a></h3><ul><li>坎之最上爻，全卦终点，下承九五，与九三相应</li><li><strong>硕</strong>：历经全程仍完整保留的成果；这是全卦**唯一明写「吉」**之处</li><li>「志在内也」——心仍系着尚在险中的九五</li></ul><p>历经全程考验，带回的是一份完整而能延续的成果。但他没有转身就走——他遇见的「大人」，正是那位靠「中节」聚拢了朋来的九五；卦辞开篇「利见大人」的承诺，在这里完整兑现。</p><blockquote><p>收束：活下来，并且不独自离场。</p></blockquote><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',27)),i(l,{title:"字词释义",items:[{term:"蹇",pinyin:["jiǎn"],meaning:"艰难、跛足、难行。是「处境」，不是「动作」——这一点靠爻辞用法钉死：四个「往蹇」中，往 + 险难名词语法通顺，往 + 止则自相矛盾，故「蹇」字本身不含「止」义。"},{term:"往",pinyin:["wǎng"],meaning:"向外、前进。泰卦「小往大来」、否卦「大往小来」皆以「往」为外出。"},{term:"来",pinyin:["lái"],meaning:"向内、退返，与「往」对举。"},{term:"反",pinyin:["fǎn"],meaning:"折返，是空间动作，不是「反躬自省」。复卦「反复其道」、泰卦九三「无往不复」。"},{term:"连",pinyin:["lián"],meaning:"联结、依靠。六四被九三、九五两阳爻环抱；取此读法的依据是小象「当位实也」的肯定语气。"},{term:"朋",pinyin:["péng"],meaning:"同类聚合，不是「友谊」。坤卦「西南得朋」「乃与类行」。"},{term:"硕",pinyin:["shuò"],meaning:"历经消耗仍完整保留的成果。剥卦上九「硕果不食」。"},{term:"誉",pinyin:["yù"],meaning:"称许、声誉。初六「来誉」，是退返本位所得的称许。"},{term:"蹇蹇",pinyin:["jiǎn","jiǎn"],meaning:"险难反复叠加。叠字表程度加深。"},{term:"匪躬",pinyin:["fěi","gōng"],meaning:"不是因自身私利所致。匪即非，躬即自身。"},{term:"大蹇",pinyin:["dà","jiǎn"],meaning:"险难的核心与责任的核心重合之处，故曰「大」。"},{term:"大人",pinyin:["dà","rén"],meaning:"德位兼备、能带人出险的人。卦辞「利见大人」，于上六兑现为九五。"},{term:"反身修德",pinyin:["fǎn","shēn","xiū","dé"],meaning:"象传语。回头修自己，而不是向外强求——蹇卦给出的第一个动作。"}]}),n[2]||(n[2]=t(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p>蹇卦讲的是<strong>处在难里</strong>。下艮（山、止）上坎（水、险）——山上又有水，水在山上走不动，人在其中进退两难。</p><p>卦辞「利西南，不利东北。利见大人，贞吉」是纲领：靠近同类、不孤军深入、守住正道、等能带你出去的人。<strong>六爻的展开，正是对这四句话的逐步兑现。</strong></p><p>需要分清两件事：卦象结构（坎上艮下）是<strong>事实</strong>；彖传从结构里读出的「见险而能止」是<strong>智慧</strong>。而「蹇」这个字在爻辞里始终只是「难」——这一点，四个「往蹇」的用例是最好的内部证据。</p><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p>因为它纠正一种默认反应：遇到难，第一反应是往前冲。</p><p>蹇卦把三种「止」摆在面前——初六那种<strong>主动选择的止</strong>（成本最低，值得称许）、六二那种<strong>不可能拥有的止</strong>（责任在身，退无可退）、九三那种<strong>结构性的止</strong>（山域边界，回头就是本位）。同样是「止」，处境完全不同。分清自己在哪一种里，才知道下一步该做什么。</p><p>而过了九三进入坎险，全卦的问题也变了：从「止还是往」，变成「靠什么活下来」。六四的「连」、九五的「朋来」，都在说同一件事：<strong>最深处的险，是靠彼此靠近渡过去的。</strong></p><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><ol><li><strong>止步成本最低时先止</strong>：还没深入，退路仍在，不必急于证明勇气（初六）</li><li><strong>责任在身时守住清白</strong>：退不了、进不得，此时的功课是不让这份苦变成怨（六二）</li><li><strong>回到本位</strong>：在边界上折返不是逃避，是回到自己站得住的地方（九三）</li><li><strong>主动联结</strong>：独自扛不住时，依靠身边的力量，先站在能左右逢源的位置上（六四）</li><li><strong>靠品质聚人</strong>：不乞求，把中正有节做实，同类自会靠拢（九五）</li><li><strong>脱险不弃同伴</strong>：走出去之后，心仍可系着还在险里的人（上六）</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>这条弧线，其实是一个完整的转变：从「独自面对止或往的选择」（下三爻），走到「必须依靠联结才能渡险」（上三爻）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>平地 → 【艮：山域】 → 【坎：险域】 → 出险</span></span>
<span class="line"><span>       止的选择空间        必须联结才能活</span></span>
<span class="line"><span>初六(来誉) 六二(蹇蹇/匪躬) 九三(来反)  六四(来连) 九五(朋来) 上六(来硕/吉)</span></span>
<span class="line"><span>  主动止      止不可得       结构性止    独自不足    中节召朋   脱险不弃</span></span></code></pre></div><p>用旅行的说法讲一遍：</p><p>你站在山上，还没下水。初六第一个面对选择——退路还在，往则遇蹇，来则得誉。这是最轻的一步，此刻止步成本最低。六二不再有这种自由：身为王臣，责任已经压下来，蹇蹇——艰难反复叠加，无法回头也无法前进，只能站在原地硬扛；他靠的不是行动，是「匪躬之故」，守住这份清白，终无尤。九三走到山的最高点，是艮之主，天生带着「止」的性向：往，前面就是险；来，回到的正是自己的本位。这一次折返，是山域给他的最后一次确认——回到自己站得住的地方，安心。</p><p>过了九三，人才真正踏进水里。六四刚入险，自知柔弱，独木难支，被两个阳爻左右环抱，于是「来连」——不是硬撑，是主动联结、依靠身边的力量。九五身处险难最深处，同时也是君位最重的责任所在，是为「大蹇」；但他中而有节，这份定力本身就像磁场，让身边的人自然靠拢——「朋来」。不是他去乞求，是他的品质本然地召唤了同类相聚。这是全卦第一次，险与援同时并存。上六走到坎的顶端，几乎已经出险：「往蹇，来硕，吉」——历经全程考验，带回的是一份完整而能延续的成果，全卦唯一明写的「吉」，落在旅程的终点。但他没有转身就走，「志在内也」，心仍系着还在险中的九五。他遇见的「大人」，正是那位靠「中节」聚拢了朋来的九五——卦辞开篇的承诺，在这里完整兑现。</p><p>核心义理：</p><ol><li><strong>处境不是动作</strong>——「蹇」描述你站在哪里（跛足难行、进退两难），不描述你该做什么；「见险而能止」是从这个处境里长出来的智慧</li><li><strong>止有三种，先分清自己在哪一种</strong>——主动的止、不可得的止、结构性的止，处境不同，功课完全不同</li><li><strong>至深之险，靠联结而非独扛</strong>——六四主动联结，九五以品质聚人，蹇卦教的不是一个人扛过艰难，而是艰难走到最深处时如何靠彼此靠近而活下来</li><li><strong>活下来之后，不独自离场</strong>——上六把全卦收在「志在内也」上</li></ol><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>读这一卦，我最受用的不是「怎么渡过难关」，而是它把「止」拆成了三种处境。以前说「知难而退」，其实就是把它们混成了一句鸡汤——退得早是明智，退得晚是怯懦。但蹇卦说：初六的止是<strong>选择</strong>，六二的止是<strong>奢望</strong>，九三的止是<strong>结构</strong>。同一张脸，三副表情。分清自己在哪一种里，是这一卦真正的入口。</p><p>「连」字在六四还留着诚实的模糊地带：既能读成「联结依靠」，也能读成「牵连拖累」。我倾向前者——依据是小象「当位实也」那句肯定语气的收束；但这一点我不当作定论，留在这里。</p><p>另有两处我想接着走：</p><ul><li>蹇卦之后接<strong>解卦</strong>（雷水解）——蹇与解、险与释，前后相连。蹇难之后终须解开，可作为读这一卦的收尾视角。</li><li>四个「往蹇」之外，蹇字在卦爻辞里的用法值得再做一次通检：把「蹇」当处境而非动作读，全卦的语法才会一致。</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：<a href="/Dao/yijing/hexagrams/03-shuileizhun">屯（第三卦）</a>、<a href="/Dao/yijing/hexagrams/40-leishuixie">解（第四十卦）</a>、<a href="/Dao/yijing/hexagrams/52-genweishan">艮（第五十二卦）</a>、<a href="/Dao/yijing/hexagrams/29-kanweishui">坎（第二十九卦）</a></li><li>蹇与屯：屯是险压着动（困难初生，宜扎根），蹇是险在山上（进退两难，宜反身修德）——初生之难与陷于难中，是两种不同的功课</li><li>蹇与解：蹇是水山（险在山上，进退两难），解是雷水（动越过险，化险为夷）——序卦「解者缓也」，蹇难之后终须解开</li><li>方位语法与坤卦「西南得朋，东北丧朋」同源：<strong>利于靠近同类，不利孤身深入</strong></li><li>相关专题：<a href="/Dao/topics/yin-yang">阴阳</a>、<a href="/Dao/topics/bian-yi">变易</a>、<a href="/Dao/topics/xiang-shu-li">象数理</a></li></ul>`,26))])}}});export{x as __pageData,b as default};
